def name_models_by_asset(apps, schema_editor):
    """Stored UI catalogs spell a model's file as the kinds 0002 knew: a hash, fetched from a URL.

    Those kinds are gone, and a catalog that still names one could not be read. A model is
    now an asset its app registers, so ``MODEL_REF`` becomes ``ASSET`` and the URL prop goes.
    """
    UICatalog = apps.get_model("facade", "UICatalog")
    for catalog in UICatalog.objects.all():
        changed = False
        for component in catalog.components or []:
            props = component.get("props") or []
            kept = [prop for prop in props if prop.get("kind") != "HTTPS_URL"]
            for prop in kept:
                if prop.get("kind") == "MODEL_REF":
                    prop["kind"] = "ASSET"
                    changed = True
            if len(kept) != len(props):
                component["props"] = kept
                changed = True
        if changed:
            catalog.save(update_fields=["components"])


